import{_ as n,o as h,c as r,a2 as i}from"./chunks/framework.B_O-p1f2.js";const l=JSON.parse('{"title":"1. Tổng quan","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/overview.md","filePath":"gdd/overview.md"}'),a={name:"gdd/overview.md"};function o(e,t,c,d,g,u){return h(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="_1-tong-quan" tabindex="-1">1. Tổng quan <a class="header-anchor" href="#_1-tong-quan" aria-label="Permalink to &quot;1. Tổng quan&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Tên</strong></td><td>Pixel Squadron</td></tr><tr><td><strong>Thể loại</strong></td><td>Puzzle sắp xếp theo màu, thời gian thực, một chạm</td></tr><tr><td><strong>Nền tảng</strong></td><td>Web, ưu tiên điện thoại màn dọc</td></tr><tr><td><strong>Engine</strong></td><td>Phaser 4, TypeScript, Vite</td></tr><tr><td><strong>Ngôn ngữ trong game</strong></td><td>Tiếng Việt</td></tr><tr><td><strong>Nguồn gốc</strong></td><td>Port từ prototype HTML/Canvas 2D một file (<code>Plane Shoot/index.html</code>), giữ nguyên luật và dữ liệu màn</td></tr></tbody></table><h2 id="_1-1-pitch" tabindex="-1">1.1 Pitch <a class="header-anchor" href="#_1-1-pitch" aria-label="Permalink to &quot;1.1 Pitch&quot;">​</a></h2><p>Phi đội máy bay bắn sạch tranh pixel theo màu. Bạn không điều khiển máy bay; bạn chỉ quyết định <strong>chiếc nào cất cánh và khi nào</strong>. Mỗi lần chạm là một lần đặt cược vào chỗ trống trên bầu trời.</p><h2 id="_1-2-nguoi-choi-muc-tieu" tabindex="-1">1.2 Người chơi mục tiêu <a class="header-anchor" href="#_1-2-nguoi-choi-muc-tieu" aria-label="Permalink to &quot;1.2 Người chơi mục tiêu&quot;">​</a></h2><p>Người chơi casual trên điện thoại, thích puzzle kiểu &quot;sort theo màu&quot; nhưng muốn có nhịp nhanh và cảm giác hành động: phiên chơi ngắn (một màn khoảng 20–60 giây), thao tác chỉ bằng một ngón cái.</p><h2 id="_1-3-tru-cot-thiet-ke" tabindex="-1">1.3 Trụ cột thiết kế <a class="header-anchor" href="#_1-3-tru-cot-thiet-ke" aria-label="Permalink to &quot;1.3 Trụ cột thiết kế&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trụ cột</th><th>Trong game</th></tr></thead><tbody><tr><td><strong>Một chạm, nhiều hệ quả</strong></td><td>Chỉ có một thao tác là chạm khoang chứa; mọi chiều sâu đến từ thứ tự cất cánh.</td></tr><tr><td><strong>Đọc được ngay</strong></td><td>Khối lộ ra có viền sáng nhấp nháy, máy bay đầu hàng có vòng xanh khi bắn được ngay, chip màu ở đầu tranh sáng lên khi màu đó đang lộ.</td></tr><tr><td><strong>Áp lực có kiểm soát</strong></td><td>Không có đồng hồ màn chơi; áp lực duy nhất là 5 chỗ và 5 giây bế tắc.</td></tr><tr><td><strong>Phần thưởng thị giác</strong></td><td>Mỗi phát trúng có mảnh vỡ, rung màn hình nhẹ, rung máy; bức tranh pixel lộ dần rồi biến mất.</td></tr></tbody></table>',8)])])}const m=n(a,[["render",o]]);export{l as __pageData,m as default};
